{
  "tasks": [
    {
      "task_id": "T1",
      "title": "销售整体概况与异常极值检测",
      "business_question": "整体销售额的总量、均值及最大最小值是多少，以识别潜在的极端异常值？",
      "priority": "P0",
      "priority_reason": "这是探索性分析的基础，直接回答“主要特征”和“异常”的核心需求。删除此任务将无法了解数据的整体量级和离散程度。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_sales"
              },
              {
                "function": "max",
                "field": "field_0005",
                "alias": "max_sales"
              },
              {
                "function": "min",
                "field": "field_0005",
                "alias": "min_sales"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "地区维度的销售分布规律",
      "business_question": "不同地区的订单数量和销售额表现如何，是否存在显著的地区差异？",
      "priority": "P0",
      "priority_reason": "地区是重要的业务维度（unique_count=2），分组统计能揭示“规律”中的结构性特征。删除此任务将丢失关键的地理分布视角。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "order_count"
              },
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "sales_sum"
              },
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "sales_avg"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "产品类别的销售贡献分析",
      "business_question": "各产品类别的销售额总和及占比情况如何，哪类产品销售表现更突出？",
      "priority": "P0",
      "priority_reason": "产品类别是另一个关键分类维度（unique_count=2），分析其销售贡献有助于理解业务构成的“主要特征”。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "category_sales_sum"
              },
              {
                "function": "count",
                "field": null,
                "alias": "category_order_count"
              }
            ],
            "dimensions": [
              "field_0007"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T4",
      "title": "时间趋势初步观察",
      "business_question": "按月份统计销售额的变化趋势，以发现潜在的时间规律或季节性特征？",
      "priority": "P1",
      "priority_reason": "虽然数据仅10行且日期唯一，但提取月份进行分组是探索“时间规律”的标准做法。若数据不足以形成趋势，该任务仍能提供基础的时间分布视图，属于补充性分析。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "month_val"
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "monthly_sales_sum"
              },
              {
                "function": "count",
                "field": null,
                "alias": "monthly_order_count"
              }
            ],
            "dimensions": [
              "month_val"
            ]
          }
        }
      ]
    }
  ]
}
